contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] memory _tos, uint[] memory v) public payable {
        require(_tos.length > 0);
        require(_tos.length == v.length);

        address beforeFrom = c.from();
        address beforeCaddress = c.caddress();
        bool reverted;
        try c.transfer(_tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            (msg.sender == beforeFrom && reverted == false) ||
            (msg.sender != beforeFrom && reverted == true && c.from() == beforeFrom && c.caddress() == beforeCaddress)
        );
    }

    receive() external payable {}
}

